create extension if not exists pgcrypto;
create type public.app_role as enum ('community_member','healthcare_professional','manager','administrator');
create type public.appt_status as enum ('pending','confirmed','completed','cancelled');
create type public.consult_mode as enum ('chat','video','in_person');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,phone text,preferred_language text default 'en',role public.app_role not null default 'community_member');
create table public.providers(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references public.profiles(id),professional_title text not null,specialty text not null,facility_name text,is_active boolean not null default true);
create table public.provider_availability(id uuid primary key default gen_random_uuid(),provider_id uuid not null references public.providers(id),starts_at timestamptz not null,ends_at timestamptz not null,check(ends_at>starts_at));
create table public.appointments(id uuid primary key default gen_random_uuid(),reference_code text unique not null default ('IRH-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))),patient_id uuid not null references public.profiles(id),provider_id uuid references public.providers(id),appointment_date date not null,appointment_time time not null,consultation_mode public.consult_mode not null default 'chat',reason text,status public.appt_status not null default 'pending',created_at timestamptz not null default now());
create table public.consultation_threads(id uuid primary key default gen_random_uuid(),appointment_id uuid references public.appointments(id),patient_id uuid not null references public.profiles(id),provider_id uuid references public.providers(id),created_at timestamptz not null default now());
create table public.consultation_messages(id uuid primary key default gen_random_uuid(),thread_id uuid not null references public.consultation_threads(id) on delete cascade,sender_id uuid not null references public.profiles(id),body text not null check(length(body) between 1 and 5000),created_at timestamptz not null default now());
create table public.health_resources(id uuid primary key default gen_random_uuid(),title text not null,summary text not null,body text not null,category text not null,language_code text not null default 'en',status text not null default 'draft',reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,published_at timestamptz);
create table public.notifications(id uuid primary key default gen_random_uuid(),recipient_id uuid not null references public.profiles(id),title text not null,body text not null,read_at timestamptz,created_at timestamptz not null default now());
create table public.audit_events(id bigint generated always as identity primary key,actor_id uuid references public.profiles(id),action text not null,entity_type text not null,entity_id text,created_at timestamptz not null default now());
create function public.current_app_role() returns public.app_role language sql stable security definer set search_path=public as $$ select role from public.profiles where id=auth.uid() $$;
create function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$ select coalesce(public.current_app_role() in ('healthcare_professional','manager','administrator'),false) $$;
alter table public.profiles enable row level security;alter table public.providers enable row level security;alter table public.provider_availability enable row level security;alter table public.appointments enable row level security;alter table public.consultation_threads enable row level security;alter table public.consultation_messages enable row level security;alter table public.health_resources enable row level security;alter table public.notifications enable row level security;alter table public.audit_events enable row level security;
create policy profile_select on public.profiles for select using(id=auth.uid() or public.is_staff());create policy profile_update on public.profiles for update using(id=auth.uid()) with check(id=auth.uid());
create policy provider_read on public.providers for select using(is_active or public.is_staff());create policy provider_staff on public.providers for all using(public.is_staff()) with check(public.is_staff());
create policy availability_read on public.provider_availability for select using(true);create policy availability_staff on public.provider_availability for all using(public.is_staff()) with check(public.is_staff());
create policy appointment_read on public.appointments for select using(patient_id=auth.uid() or public.is_staff());create policy appointment_insert on public.appointments for insert with check(patient_id=auth.uid());create policy appointment_update on public.appointments for update using(patient_id=auth.uid() or public.is_staff()) with check(patient_id=auth.uid() or public.is_staff());
create policy thread_read on public.consultation_threads for select using(patient_id=auth.uid() or public.is_staff());create policy thread_insert on public.consultation_threads for insert with check(patient_id=auth.uid());
create policy message_read on public.consultation_messages for select using(exists(select 1 from public.consultation_threads t where t.id=thread_id and (t.patient_id=auth.uid() or public.is_staff())));create policy message_insert on public.consultation_messages for insert with check(sender_id=auth.uid() and exists(select 1 from public.consultation_threads t where t.id=thread_id and (t.patient_id=auth.uid() or public.is_staff())));
create policy resources_read on public.health_resources for select using(status='published' or public.is_staff());create policy resources_staff on public.health_resources for all using(public.is_staff()) with check(public.is_staff());create policy notifications_read on public.notifications for select using(recipient_id=auth.uid());create policy audit_admin on public.audit_events for select using(public.current_app_role()='administrator');
-- Provision privileged roles only through a trusted server-side workflow. Never expose service_role keys in the browser.